import java.nio.file.Files;
import java.nio.file.Path;

public final class CartTest {
    public static void main(String[] args) throws Exception {
        int limit = Integer.parseInt(Files.readString(Path.of("max_items.txt")).trim());
        if (!Cart.canAdd(limit)) throw new AssertionError("canAdd(" + limit + ") should be true");
        if (Cart.canAdd(limit + 1)) throw new AssertionError("canAdd(" + (limit + 1) + ") should be false (stale limit not updated)");
        System.out.println("all tests passed");
    }
}

