import java.nio.file.Files;
import java.nio.file.Path;

public final class Cart {
    public static boolean canAdd(int count) throws Exception {
        int limit = Integer.parseInt(Files.readString(Path.of("max_items.txt")).trim());
        return count <= limit;
    }
}

